const el = (t, a = {}, p) => { const n = document.createElementNS(NS, t);
  for (const k in a) n.setAttribute(k, a[k]); if (p) p.appendChild(n); return n; };
const esc = s => String(s).replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));

/* number formatting by measure family */
const fmtVal = (v, unit) => unit === "pct"
  ? (v * 100).toFixed(1) + "%"
  : (v >= 0 ? "" : "") + v.toFixed(2);
const signed = (v, d = 2) => (v > 0 ? "+" : "") + v.toFixed(d);

/* drawn marks — no glyph fonts, one stroke language ------------------------ */
function markOut(size = 11) {
  // a filled caret: the chart convention for a value outside its range
  return `<svg width="${size}" height="${size}" viewBox="0 0 12 12" aria-hidden="true">
    <path d="M6 1.4 11 10.4 1 10.4Z" fill="${C("--out")}"/></svg>`;
}
function markObs(size = 11) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 12 12" aria-hidden="true">
    <circle cx="6" cy="6" r="3.6" fill="${C("--obs")}"/></svg>`;
}

/* ------------------------------------------------------------------ header */
const M = D.meta;
document.getElementById("oppName").textContent = M.opponent;
document.getElementById("resultVal").textContent = `${M.result}  ${M.team_score}–${M.opp_score}`;
document.getElementById("wkVal").textContent = `${M.season} · Week ${String(M.week).padStart(2, "0")}`;
document.getElementById("dateVal").textContent = M.date_short;
document.getElementById("venueVal").textContent = M.venue;
document.getElementById("nextVal").textContent = M.next_short;
document.getElementById("p4note").textContent = `Baylor's season value against all ${D.p4_n} Power Four teams`;
document.getElementById("p4count").textContent = D.p4_n;
document.getElementById("nextNote").textContent = M.next_game;
// every remaining opponent- or week-specific string on the sheets, filled from meta
const NO = M.next_opponent;
document.getElementById("noName1").textContent = NO;
document.getElementById("noNote2").textContent = `${NO} against the same Power Four ranges`;
document.getElementById("noHeadOff").textContent = `${NO} offense`;
document.getElementById("noHeadDef").textContent = `${NO} defense`;
document.getElementById("noColOff").textContent = NO;
document.getElementById("noColDef").textContent = NO;
document.getElementById("traceNote").textContent =
  `EPA per play by week, ${M.season_range}`;

/* ======================================================== 1. game trace */
(function trace() {
  const box = document.getElementById("traceBox");
  const pts = D.winprob;
  const W = 1000, H = 190, mL = 34, mR = 10, mT = 10, mB = 20;
  const iw = W - mL - mR, ih = H - mT - mB;
  const X = i => mL + (i / (pts.length - 1)) * iw;
  const Y = v => mT + (1 - v) * ih;
  document.getElementById("traceHdr").textContent =
    `Win probability, Baylor, all ${pts.length - 1} plays`;
  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img",
    "aria-label": "Baylor win probability across the game" }, box);

  // ruled chart paper behind the trace
  for (let v = 0; v <= 1.0001; v += .25) {
    el("line", { x1: mL, x2: W - mR, y1: Y(v), y2: Y(v),
      stroke: v === .5 ? C("--rule") : C("--rule-hair"),
      "stroke-width": v === .5 ? 1 : .75,
      "stroke-dasharray": v === .5 ? "4 3" : "none" }, svg);
    const t = el("text", { x: mL - 6, y: Y(v) + 3, "text-anchor": "end",
      "font-family": C("--mono"), "font-size": 8, fill: C("--ink-3") }, svg);
    t.textContent = Math.round(v * 100) + "%";
  }
  // No quarter rules: the win-probability feed carries no period or clock field, so
  // quarter boundaries cannot be derived. Plays are not evenly distributed across
  // quarters, so an evenly-spaced rule would be a fabricated axis. The x-axis is the
  // play sequence and is labelled as such.
  let d = "";
  pts.forEach((p, i) => { d += (i ? "L" : "M") + X(i).toFixed(1) + " " + Y(p.wp).toFixed(1); });
  el("path", { d, fill: "none", stroke: C("--obs"), "stroke-width": 1.6,
    "stroke-linejoin": "round" }, svg);

  // scoring events ticked on the trace and numbered to the table below
  D.score_events.forEach((e, n) => {
    const i = pts.findIndex(p => p.p === e.p);
    if (i < 0) return;
    const x = X(i), y = Y(e.wp);
    el("line", { x1: x, x2: x, y1: mT + ih, y2: y, stroke: C("--ink-3"),
      "stroke-width": .75, "stroke-dasharray": "2 2" }, svg);
    el("circle", { cx: x, cy: y, r: 3, fill: C("--paper"), stroke: C("--ink"),
      "stroke-width": 1.2 }, svg);
    const t = el("text", { x, y: mT + ih + 13, "text-anchor": "middle",
      "font-family": C("--mono"), "font-size": 7.5, fill: C("--ink-2") }, svg);
    t.textContent = n + 1;
  });
  const lastT = el("text", { x: W - mR, y: Y(1) + 9, "text-anchor": "end",
    "font-family": C("--mono"), "font-size": 8, fill: C("--ink-2") }, svg);
  lastT.textContent = `FINAL ${M.team_score}–${M.opp_score}`;
  const axT = el("text", { x: mL, y: H - 6, "font-family": C("--mono"),
    "font-size": 8, fill: C("--ink-3") }, svg);
  axT.textContent = `PLAY 1 → ${pts.length - 1}`;

  document.getElementById("traceLegend").innerHTML =
    `<span>${markObs(9)} Baylor win probability</span>` +
    `<span><svg width="11" height="11" viewBox="0 0 12 12" aria-hidden="true">
       <circle cx="6" cy="6" r="3.6" fill="${C("--paper")}" stroke="${C("--ink")}" stroke-width="1.4"/></svg>
       Scoring play, numbered below</span>` +
    `<span>Horizontal axis is play sequence, not clock time</span>`;

  // swing colour is direction, not magnitude: blue when it moved toward Baylor,
  // oxide when it moved away. Magnitude is carried by the number itself.
  document.getElementById("eventRows").innerHTML = D.score_events.map((e, n) => `
    <tr>
      <td>${n + 1}</td>
      <td class="lbl clip">${esc(e.text)}</td>
      <td class="r">${e.hs}–${e.as}</td>
      <td class="r">${Math.round(e.wp * 100)}%</td>
      <td class="r ${e.swing >= 0 ? "gain" : "loss"}">${signed(e.swing * 100, 0)} pts</td>
    </tr>`).join("");
})();

/* ================================================= 2. game observations */
(function obs() {
  const g = D.ppa_game, s = D.ppa_season, b = D.box, t = D.tempo;
  const rows = [
    { l: "Offense EPA per play", a: g.offense.overall, b: s.offense.overall, better: 1 },
    { l: "Offense EPA, 1st down", a: g.offense.firstDown, b: s.offense.firstDown, better: 1 },
    { l: "Offense EPA, 2nd down", a: g.offense.secondDown, b: s.offense.secondDown, better: 1 },
    { l: "Offense EPA, 3rd down", a: g.offense.thirdDown, b: s.offense.thirdDown, better: 1 },
    { l: "Defense EPA per play allowed", a: g.defense.overall, b: s.defense.overall, better: -1 },
    { l: "Defense EPA allowed, 3rd down", a: g.defense.thirdDown, b: s.defense.thirdDown, better: -1 },
  ];
  const bx = D.box_snaps;
  const extra = [
    { l: "Offensive snaps", a: bx.off, b: null, raw: true,
      note: `${bx.off_drives} drives, ${(bx.off / bx.off_drives).toFixed(1)} per drive` },
    { l: "Defensive snaps", a: bx.def, b: null, raw: true,
      note: `${bx.def_drives} drives, ${(bx.def / bx.def_drives).toFixed(1)} per drive` },
    { l: "Yards per drive", a: t.baylor_off.yards_per_drive, b: null, raw: true,
      note: `allowed ${t.baylor_def.yards_per_drive}` },
  ];
  // "below season" was printing beside a positive change on the defensive rows, where a
  // higher number is worse. Name the direction instead of the rank.
  const readingOf = r => {
    const d = r.a - r.b;
    if (Math.abs(d) < 0.03) return "in line with season";
    if (r.better === 1) return d > 0 ? "better than season" : "worse than season";
    return d > 0 ? "allowing more than season" : "allowing less than season";
  };
  document.getElementById("obsRows").innerHTML =
    rows.map(r => {
      const d = r.a - r.b, good = d * r.better > 0;
      return `<tr>
      <td class="lbl">${r.l}</td>
      <td class="r">${signed(r.a)}</td>
      <td class="r mid">${signed(r.b)}</td>
      <td class="r ${good ? "gain" : "loss"}">${signed(d)}</td>
      <td class="lbl" style="font-size:9.5pt;color:${good ? "var(--ink-2)" : "var(--ink)"}">${readingOf(r)}</td>
    </tr>`;
    }).join("") +
    extra.map(r => `<tr>
      <td class="lbl">${r.l}</td>
      <td class="r">${r.a}</td>
      <td class="r mid">—</td>
      <td class="r mid">—</td>
      <td class="lbl mid" style="font-size:9.5pt">${r.note}</td>
    </tr>`).join("");
})();

/* ================================================== 3. reference ranges */
function bandTrack(r, w = 300) {
  const h = 15, pad = 6;
  const lo = Math.min(r.lo, r.value), hi = Math.max(r.hi, r.value);
  const span = hi - lo || 1;
  const X = v => pad + ((v - lo) / span) * (w - pad * 2);
  const flip = r.direction === -1;   // draw so that "further right is better" always holds
  const P = v => flip ? (w - X(v)) : X(v);
  const mid = h / 2;
  const boxL = Math.min(P(r.p25), P(r.p75)), boxR = Math.max(P(r.p25), P(r.p75));
  const whL = Math.min(P(r.p10), P(r.p90)), whR = Math.max(P(r.p10), P(r.p90));
  const vx = P(r.value);
  const col = r.flag ? C("--out") : C("--obs");
  return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img"
      aria-label="${r.label}: Baylor ${fmtVal(r.value, r.unit)}, Power Four median ${fmtVal(r.p50, r.unit)}, ${Math.round(r.pctl)}th percentile">
    <line x1="${whL}" y1="${mid}" x2="${whR}" y2="${mid}" stroke="${C("--rule")}" stroke-width="1"/>
    <line x1="${whL}" y1="${mid - 3.5}" x2="${whL}" y2="${mid + 3.5}" stroke="${C("--rule")}" stroke-width="1"/>
    <line x1="${whR}" y1="${mid - 3.5}" x2="${whR}" y2="${mid + 3.5}" stroke="${C("--rule")}" stroke-width="1"/>
    <rect x="${boxL}" y="${mid - 5}" width="${Math.max(1, boxR - boxL)}" height="10"
          fill="${C("--ref")}" stroke="${C("--rule")}" stroke-width=".75"/>
    <line x1="${P(r.p50)}" y1="${mid - 6}" x2="${P(r.p50)}" y2="${mid + 6}"
          stroke="${C("--ink-2")}" stroke-width="1.25"/>
    ${r.flag
      ? `<path d="M${vx} ${mid - 5.6} L${vx + 4.6} ${mid + 4.4} L${vx - 4.6} ${mid + 4.4}Z"
             fill="${col}" stroke="${C("--paper")}" stroke-width="1"/>`
      : `<circle cx="${vx}" cy="${mid}" r="4" fill="${col}" stroke="${C("--paper")}" stroke-width="1.1"/>`}
  </svg>`;
}

function renderBands(id, rows) {
  document.getElementById(id).innerHTML = rows.map(r => `
    <tr class="${r.flag ? "flagged" : ""}">
      <td class="lbl">${r.label}</td>
      <td class="r ${r.flag ? "out" : ""}">${fmtVal(r.value, r.unit)}</td>
      <td class="r mid">${fmtVal(r.p50, r.unit)}</td>
      <td class="trk"><div class="track">${bandTrack(r)}</div></td>
      <td class="r ${r.flag ? "out" : ""}">${Math.round(r.pctl)}</td>
    </tr>`).join("");
}

