/* ================================================== 5. next opponent */
(function next() {
  const off = D.next_bands.filter(r => r.side === "off");
  const def = D.next_bands.filter(r => r.side === "def");
  const best = a => a.reduce((m, r) => (r.pctl > m.pctl ? r : m));
  const worst = a => a.reduce((m, r) => (r.pctl < m.pctl ? r : m));
  const P = v => Math.round(v) + ordinal(Math.round(v)) + " percentile";
  // These cards rank a profile; they do not report out-of-range values, so they must
  // NOT reuse the ● / ▲ marks, which sheet 2 defines as inside / outside the P4 range.
  // Their own mark is a rank bar: how far from the conference middle, in which direction.
  const rankMark = r => {
    const w = 22, h = 13, mid = h / 2, half = (w - 2) / 2;
    const off50 = (r.pctl - 50) / 50;              // -1 .. +1
    const x = 1 + half + off50 * half;
    const col = r.pctl >= 50 ? C("--obs") : C("--out");
    return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true">
      <line x1="1" y1="${mid}" x2="${w - 1}" y2="${mid}" stroke="${C("--rule")}" stroke-width="1"/>
      <line x1="${1 + half}" y1="2" x2="${1 + half}" y2="${h - 2}" stroke="${C("--ink-3")}" stroke-width="1"/>
      <rect x="${Math.min(1 + half, x)}" y="${mid - 2.6}" width="${Math.max(1.5, Math.abs(x - (1 + half)))}"
            height="5.2" fill="${col}"/></svg>`;
  };
  const cards = [
    { t: "What they lean on", r: best(off),
      b: r => `${NO}'s <b>${r.label}</b> is ${fmtVal(r.value, r.unit)} — the ` +
        `${P(r.pctl)} of the Power Four. It is the most reliable thing their offense does.` },
    { t: "What they cannot do", r: worst(off),
      b: r => `Their <b>${r.label}</b> is ${fmtVal(r.value, r.unit)} — the ${P(r.pctl)}. ` +
        `Force them into this and the drive stalls.` },
    { t: "Where we attack", r: worst(def),
      b: r => `${NO}'s defense ranks in the ${P(r.pctl)} for <b>${r.label}</b>, at ` +
        `${fmtVal(r.value, r.unit)}. Softest ground on their side of the ball.` },
  ];
  document.getElementById("nextFindings").innerHTML =
    cards.map(c => findingCard(rankMark(c.r), c.t, c.b(c.r))).join("") +
    `<div class="finding"><div class="fmark"></div><div class="ftext">
       <div class="fbody" style="color:var(--ink-3);font-size:9pt">
         The bar on each row shows distance from the Power Four median — right of the
         rule is above it, left is below. These rank a profile; they are not the
         out-of-range marks used on sheet 2.</div></div></div>`;

  // keep the "allowed" suffix: under a DEFENSE heading, "Success rate" alone reads as
  // their production rather than what they concede.
  const mini = rows => rows.map(r => `
    <tr class="${r.flag ? "flagged" : ""}">
      <td class="lbl" style="font-size:9.5pt">${r.label}</td>
      <td class="r ${r.flag ? "out" : ""}">${fmtVal(r.value, r.unit)}</td>
      <td class="trk" style="width:1.2in"><div class="track">${bandTrack(r, 130)}</div></td>
      <td class="r ${r.flag ? "out" : ""}">${Math.round(r.pctl)}</td>
    </tr>`).join("");
  document.getElementById("nextOff").innerHTML = mini(off);
  document.getElementById("nextDef").innerHTML = mini(def);
})();

/* ================================================= 6. season trace rows */
// Offense EPA and defense EPA-allowed have opposite polarity, so they cannot share one
// left-to-right axis without contradicting sheet 2's rule that further right is better.
// The plotted quantity is their difference — net EPA per play — which is polarity-correct
// by construction. Both source values stay in their own columns.
(function weeks() {
  const rows = D.epa_by_week.filter(r => r.week <= D.meta.week)
    .map(r => ({ ...r, net: r.off - r.def }));
  const mag = Math.max(...rows.map(r => Math.abs(r.net))) || 1;
  const W = 220, h = 15, pad = 5, zero = W / 2;
  const X = v => zero + (v / mag) * (zero - pad);
  document.getElementById("weekRows").innerHTML = rows.map(r => `
    <tr class="${r.week === D.meta.week ? "flagged" : ""}">
      <td>${r.week}</td>
      <td class="lbl">${esc(r.opponent)}</td>
      <td class="r">${signed(r.off)}</td>
      <td class="r">${signed(r.def)}</td>
      <td class="r" style="font-weight:600;color:${r.net >= 0 ? C("--obs") : C("--out")}">${signed(r.net)}</td>
      <td class="trk" style="width:1.9in"><div class="track">
        <svg viewBox="0 0 ${W} ${h}" preserveAspectRatio="none" role="img"
             aria-label="Week ${r.week} versus ${esc(r.opponent)}: net EPA per play ${signed(r.net)}">
          <line x1="${pad}" y1="${h / 2}" x2="${W - pad}" y2="${h / 2}" stroke="${C("--rule-hair")}"/>
          <line x1="${zero}" y1="1" x2="${zero}" y2="${h - 1}" stroke="${C("--ink-3")}" stroke-width="1"/>
          <rect x="${Math.min(zero, X(r.net))}" y="${h / 2 - 3.4}"
                width="${Math.max(1.5, Math.abs(X(r.net) - zero))}" height="6.8"
                fill="${r.net >= 0 ? C("--obs") : C("--out")}"/>
        </svg></div></td>
    </tr>`).join("");
  document.getElementById("weekLegend").innerHTML =
    `<span>Net = offense EPA per play minus defense EPA per play allowed</span>` +
    `<span>Right of the rule is a positive week, left is negative — further right is better</span>` +
    `<span>${M.week_label.replace(/^w/, "W")} is shaded</span>`;
})();

function ordinal(n) {
  const s = ["th", "st", "nd", "rd"], v = n % 100;
  return s[(v - 20) % 10] || s[v] || s[0];
}
</script>

