const D = JSON.parse(document.getElementById("payload").textContent);
const NS = "http://www.w3.org/2000/svg";
const CSS = getComputedStyle(document.documentElement);
const C = k => CSS.getPropertyValue(k).trim();
const esc = s => String(s).replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
const signed = (v, d = 0) => {
  const s = v.toFixed(d);
  return (Number(s) === 0 ? "0" + (d ? "." + "0".repeat(d) : "") : (v > 0 ? "+" : "") + s);
};
const snaps = n => `${n} snap${n === 1 ? "" : "s"}`;
const WEEK = D.meta.week;

function markOut(size = 11) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 12 12" aria-hidden="true">
    <path d="M6 1.4 11 10.4 1 10.4Z" fill="${C("--out")}"/></svg>`;
}
function markLow(size = 11) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 12 12" aria-hidden="true">
    <path d="M6 10.6 1 1.6 11 1.6Z" fill="${C("--out")}"/></svg>`;
}
function markObs(size = 11) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 12 12" aria-hidden="true">
    <circle cx="6" cy="6" r="3.6" fill="${C("--obs")}"/></svg>`;
}

/* ------------------------------------------------------------------ header */
const players = D.season_players.filter(p => p.this_week > 0);
document.getElementById("oppName").textContent = D.meta.opponent;
document.getElementById("totalSnaps").textContent =
  players.reduce((s, p) => s + p.this_week, 0).toLocaleString();
document.getElementById("wkVal").textContent = `${D.meta.season} · Week ${String(WEEK).padStart(2, "0")}`;
document.getElementById("nPlayers").textContent = players.length;
document.getElementById("nextVal").textContent = D.meta.next_short;
document.getElementById("nextNote").textContent = D.meta.next_game;
document.getElementById("dateVal").textContent = D.meta.date_short;
document.getElementById("baseProse1").textContent = D.meta.baseline_range_prose;
document.querySelectorAll(".baseRange").forEach(n => n.textContent = D.meta.baseline_range);
