input.command:
grep -n '\.block\|\.legend{\|\.foot{\|\.protonote\|\.finding{\|\.fmark\|\.sheet{\|\.h2note\|\.colhead\|font-size:7\|font-size:8\|font-size:9' prototype_b_demand.tpl.html | head -40; echo "=== python contrast ==="; python3 - <<'EOF'
def lin(c):
    c=c/255
    return c/12.92 if c<=0.03928 else ((c+0.055)/1.055)**2.4
def L(h):
    h=h.lstrip('#'); r,g,b=(int(h[i:i+2],16) for i in (0,2,4))
    return 0.2126*lin(r)+0.7152*lin(g)+0.0722*lin(b)
def cr(a,b):
    la,lb=L(a),L(b); hi,lo=max(la,lb),min(la,lb)
    return (hi+0.05)/(lo+0.05)
paper='#f4f5f1'; band='#e6ece3'; ref='#ccd6d9'; desk='#c9ccc3'
for name,c in [('ink #15181a','#15181a'),('ink-2 #454e4b','#454e4b'),('ink-3 #5d6763','#5d6763'),('ink-3 OLD #6d7773','#6d7773'),('obs #2a6ea3','#2a6ea3'),('out #b8433a','#b8433a'),('rule #aab3ac','#aab3ac'),('rule-hair #c6cdc5','#c6cdc5'),('ref #ccd6d9','#ccd6d9')]:
    print(f"{name:22s} on paper {cr(c,paper):5.2f}  on band {cr(c,band):5.2f}  on ref-fill {cr(c,ref):5.2f}  on flagged #f6e6e3 {cr(c,'#f6e6e3'):5.2f}")
print()
print('ref fill vs paper (graphic 3:1 rule):', round(cr(ref,paper),2))
print('rule vs paper:', round(cr('#aab3ac',paper),2))
print('rule-hair vs paper:', round(cr('#c6cdc5',paper),2))
EOF

